mapper.select:
SELECT fi.id, fi.fba_shipment_id, fi.warehouse_id, fi.warehouse_name, fi.asin, fi.msku, fi.fn_sku, fi.sku_no, fi.product_name, fi.delivery_channels, fi.fbm_fulfillable_qty, fi.inbound_working_qty, fi.inbound_shipped_qty, fi.inbound_receiving_qty, fi.fulfillable_qty, fi.reserved_qty, fi.researching_qty, fi.unsellable_qty, fi.inventory_age_0_to_30_days, fi.inventory_age_31_to_60_days, fi.inventory_age_61_to_90_days, fi.inventory_age_91_to_180_days, fi.inventory_age_181_to_270_days, fi.inventory_age_271_to_365_days, fi.inventory_age_365_plus_days, fi.update_time FROM fba_inventory fi WHERE ${params.sqlMap.default} and fi.is_deleted = FALSE
AND id IN
#{id}
AND fi.warehouse_id in
#{warehouseId}
AND fi.asin ILIKE concat('%',#{params.asin}::text,'%')
AND fi.fn_sku ILIKE concat('%',#{params.fnSku}::text,'%')
AND fi.msku ILIKE concat('%',#{params.msku}::text,'%')
AND fi.delivery_channels in
#{deliveryChannels}
AND fi.update_time >= #{params.updateTimeList[0]} and (#{params.updateTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > fd.update_time
AND NOT EXISTS (SELECT id FROM fba_inventory f WHERE f.id = fi.id AND fi.fbm_fulfillable_qty = 0 AND fi.inbound_working_qty = 0 AND fi.inbound_shipped_qty = 0 AND fi.inbound_receiving_qty = 0 AND fi.fulfillable_qty = 0 AND fi.reserved_qty = 0 AND fi.researching_qty = 0 AND fi.unsellable_qty = 0)
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
fi.create_time DESC

SELECT SUM(fi.fbm_fulfillable_qty) AS fbmFulfillableQty, SUM(fi.inbound_working_qty) AS inboundWorkingQty, SUM(fi.inbound_shipped_qty) AS inboundShippedQty, SUM(fi.inbound_receiving_qty) AS inboundReceivingQty, SUM(fi.fulfillable_qty) AS fulfillableQty, SUM(fi.reserved_qty) AS reservedQty, SUM(fi.researching_qty) AS researchingQty, SUM(fi.unsellable_qty) AS unsellableQty FROM fba_inventory fi WHERE fi.is_deleted = FALSE
AND fi.warehouse_id in
#{warehouseId}
AND fi.asin ILIKE concat('%',#{params.asin}::text,'%')
AND fi.fn_sku ILIKE concat('%',#{params.fnSku}::text,'%')
AND fi.msku ILIKE concat('%',#{params.msku}::text,'%')
AND fi.delivery_channels in
#{deliveryChannels}
AND fi.update_time >= #{params.updateTimeList[0]} and (#{params.updateTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > fd.update_time
${params.permissionSql}

SELECT id, warehouse_id, sku_no, asin, msku, fn_sku as fnsku, product_name AS platformProductName, fulfillable_qty as fulfillableQty, fbm_fulfillable_qty as fbmFulfillableQty FROM fba_inventory WHERE is_deleted= false
AND warehouse_id in
#{warehouseId}
AND sku_no in
#{skuNo}
order by sku_no,fulfillable_qty desc
